# (first_word, last_word, kind, arabic, malay, ref)  -- indices into words.json
H = "h"; Q = "q"; S = "s"
SHAHADAH = "أَنْ لَا إِلَهَ إِلَّا اللهُ وَأَنَّ مُحَمَّدًا رَسُولُ اللهِ"
CUES = [
 (0, 1, S, "", "Hadis kelapan:", ""),
 (2, 15, H, "عَنْ ابنِ عُمَرَ رضِيَ الله تَعالَى عَنْهُما أن رَسُولَ اللهِ ﷺ قَالَ:",
  "Daripada Ibn Umar رضي الله عنهما, dia berkata: Rasulullah ﷺ bersabda:", ""),
 (16, 34, H, "«أمِرْتُ أَنْ أُقَاتِلَ النَّاسَ حتَّى يَشْهَدُوا أنْ لا إلَهَ إلَّا الله، وأنّ مُحَمَّداً رسولُ اللهِ، ويُقِيموا الصَّلاةَ، ويُؤْتُوا الزَّكاةَ»",
  "“Aku diperintahkan untuk memerangi manusia sehinggalah mereka menyaksikan bahawa tiada Tuhan yang berhak disembah melainkan Allah, dan sesungguhnya Muhammad itu utusan Allah. Mereka mendirikan solat dan mengeluarkan zakat.", ""),
 (35, 45, H, "«فإذَا فَعَلوا ذلكَ»",
  "Jika mereka melakukan sedemikian — iaitu beriman, mengucap dua kalimah syahadah, mendirikan solat dan menunaikan zakat —", ""),
 (46, 52, H, "«عَصَمُوا مِنِّي دِماءَهُم وأموالَهُم»",
  "maka terpeliharalah darah dan harta mereka daripada aku,” kerana mereka telah menjadi Muslim.", ""),
 (53, 61, H, "«إلَّا بحَقِّ الإسلامِ، وحِسَابُهُم على اللَّه تَعالَى»",
  "“kecuali dengan hak Islam, dan segala perhitungan amal mereka adalah tertakluk kepada Allah Ta‘ala.”", "Riwayat al-Bukhari dan Muslim — Hadis 40, no. 8"),
 (62, 75, S, "", "Sabdanya “sehingga mereka bersaksi”, iaitu aku memerangi mereka sehingga mereka bersaksi. Perkataan “sehingga” ini menunjukkan hujung matlamat: sehingga mereka bersaksi.", ""),
 (76, 85, S, "", "Ketika Nabi ﷺ mengutus Muaz ke Yaman,", ""),
 (86, 115, H, "«فَلْيَكُنْ أَوَّلَ مَا تَدْعُوهُمْ إِلَيْهِ شَهَادَةُ " + SHAHADAH + "، فَإِنَّهُمْ أَطَاعُوا لِذَلِكَ فَأَعْلِمْهُمْ بِالصَّلَاةِ وَالزَّكَاةِ»",
  "baginda bersabda kepadanya: “Hendaklah perkara pertama yang engkau seru mereka kepadanya ialah syahadah bahawa tiada tuhan melainkan Allah dan Muhammad itu utusan Allah. Jika mereka mentaati itu, maka beritahulah mereka tentang solat dan zakat.”", ""),
 (116, 130, S, "", "Beginilah Nabi ﷺ — selawat dan salam Tuhanku ke atasnya — memulakan dengan yang terpenting, kemudian yang penting.", ""),
 (131, 137, S, "", "Adakah cukup seseorang beriman tanpa melafazkan dua kalimah syahadah?", ""),
 (138, 150, S, "", "Jika dia berkata: aku beriman dengan hatiku, aku membenarkan dengan hatiku, tetapi tidak melafazkan syahadah — itu tidak mencukupi.", ""),
 (151, 167, S, "", "Abu Talib, bapa saudara Nabi ﷺ, tahu bahawa Nabi itu benar dan berada di atas agama yang hak,", ""),
 (168, 179, S, "", "tetapi dia tidak mengakui, tidak melafazkan dua kalimah syahadah — dia enggan mengucapkannya.", ""),
 (180, 191, S, "", "Maka tidak bermanfaat baginya apa yang diyakini hatinya tentang kebenaran Nabi ﷺ,", ""),
 (192, 206, S, "", "sehingga dia melafazkan dengan lidahnya: “Aku bersaksi bahawa tiada tuhan melainkan Allah, dan aku bersaksi bahawa Muhammad itu utusan Allah.”", ""),
 (207, 215, S, "", "Jika tidak, Abu Talib telah berkata dalam syairnya yang masyhur tentang dirinya:", ""),
 (216, 228, S, "", "Katanya kepada Nabi ﷺ: “Engkau menyeru aku, dan engkau menyangka engkau penasihatku —", ""),
 (229, 235, S, "", "sesungguhnya engkau benar, dan sebelum ini engkau memang seorang yang amanah.", ""),
 (236, 245, S, "", "Sesungguhnya aku tahu agama Muhammad adalah sebaik-baik agama makhluk.", ""),
 (246, 254, S, "", "Kalaulah bukan kerana celaan atau takut dicerca, nescaya engkau dapati aku bermurah hati menerimanya dengan jelas.”", ""),
 (255, 267, S, "", "Ini menjelaskan bahawa yang menghalangnya daripada mengikuti Nabi ﷺ dan melafazkan dua kalimah syahadah", ""),
 (268, 276, S, "", "ialah rasa malu kepada orang ramai — na‘udzu billah — malu kepada orang ramai.", ""),
 (277, 288, S, "", "Bahkan dalam sesetengah riwayat — dalam kitab-kitab sejarah — bahawa dia berkata:", ""),
 (289, 305, S, "", "“Aku malu apabila sujud, punggungku terangkat lebih tinggi daripada kepalaku” — iaitu kepalaku di bumi dan punggungku di atas.", ""),
 (306, 318, S, "", "Kesombongan! Kesombongan inilah yang menghalangnya daripada mengikuti Nabi ﷺ.", ""),
 (319, 325, S, "", "Dan pembenar bagi semua itu ialah firman Allah Tabaraka wa Ta‘ala:", ""),
 (326, 339, Q, "قَدْ نَعْلَمُ إِنَّهُۥ لَيَحْزُنُكَ ٱلَّذِى يَقُولُونَ ۖ فَإِنَّهُمْ لَا يُكَذِّبُونَكَ وَلَـٰكِنَّ ٱلظَّـٰلِمِينَ بِـَٔايَـٰتِ ٱللَّهِ يَجْحَدُونَ",
  "“Sesungguhnya Kami mengetahui bahawa apa yang mereka katakan itu akan menyebabkan engkau (wahai Muhammad) berdukacita; (maka janganlah engkau berdukacita) kerana sebenarnya mereka bukan mendustakanmu, tetapi orang-orang yang zalim itu mengingkari ayat-ayat keterangan Allah…”", "Surah al-An‘am, 6:33"),
 (340, 344, S, "", "Sabdanya: “Aku diperintahkan untuk memerangi manusia.”", ""),
 (345, 355, S, "", "Peperangan dalam Islam bukanlah matlamat pada dirinya. Jihad bukan matlamat — jihad ialah wasilah", ""),
 (356, 366, S, "", "untuk merealisasikan satu matlamat. Apakah matlamatnya? Supaya Allah disembah semata-mata, Maha Suci dan Maha Tinggi Dia.", ""),
 (367, 379, S, "", "Jika kita tidak memerlukan jihad kerana semua manusia sudah Muslim, siapa lagi yang hendak kita jihadi? Tiada seorang pun.", ""),
 (380, 398, S, "", "Maka jihad bukanlah matlamat pada dirinya seperti ibadah dan seumpamanya; ia hanyalah wasilah untuk mencapai matlamat — wasilah supaya Allah disembah semata-mata.", ""),
 (399, 410, S, "", "Oleh itu Nabi ﷺ, seperti dalam hadis Buraidah, bersabda:", ""),
 (411, 432, H, "«إِذَا حَاصَرْتَ أَهْلَ حِصْنٍ فَلْيَكُنْ أَوَّلَ مَا تَدْعُوهُمْ إِلَيْهِ شَهَادَةُ " + SHAHADAH + "»",
  "“Apabila engkau mengepung penduduk sebuah kubu, hendaklah perkara pertama yang engkau seru mereka kepadanya ialah syahadah bahawa tiada tuhan melainkan Allah dan Muhammad itu utusan Allah.”", ""),
 (433, 444, S, "", "Jika mereka telah mengucapkannya — iaitu dua kalimah syahadah — maka perintahkan mereka berhijrah. Hijrah pada permulaan Islam adalah wajib.", ""),
 (445, 455, S, "", "Baginda bersabda: suruh mereka berhijrah; jika mereka taat, mereka mendapat hak kaum Muslimin dan menanggung kewajipan mereka.", ""),
 (456, 466, S, "", "Jika mereka enggan berhijrah, mereka seperti Arab badwi Muslim, tiada hak bagi mereka dalam harta fai’.", ""),
 (467, 477, S, "", "Jika mereka enggan itu juga, perintahkan mereka membayar jizyah — membayar jizyah sebagai balasan kekal atas agama mereka.", ""),
 (478, 482, S, "", "Jika mereka enggan juga, mohonlah pertolongan Allah dan perangilah mereka.", ""),
 (483, 490, S, "", "Maka peperangan itu tidak dimaksudkan pada dirinya, dan tidak dituntut pada asalnya,", ""),
 (491, 500, S, "", "tetapi peperangan itu terhadap sesiapa yang menghalang agama Allah Tabaraka wa Ta‘ala daripada tersebar.", ""),
 (501, 511, S, "", "Maka kita tidak memerangi manusia supaya mereka masuk Islam, seperti yang kita katakan semalam.", ""),
 (512, 522, S, "", "Kerana Islam tidak memerlukan orang upahan; ia tidak mahu orang upahan dan tidak mahu orang munafik.", ""),
 (523, 531, S, "", "Jihad hanyalah fardu kifayah dan wasilah, bukan matlamat pada dirinya.", ""),
 (532, 539, S, "", "Dua kalimah syahadah, seperti dalam hadis: “maka mereka telah mengucapkannya” — iaitu dua kalimah syahadah —", ""),
 (540, 545, H, "«عَصَمُوا مِنِّي دِماءَهُم وأموالَهُم»", "“terpelihara darah dan harta mereka daripada aku.” Syahadah memelihara.", ""),
 (546, 556, S, "", "Oleh itu, orang munafik hidup di kalangan kaum Muslimin; mereka tidak dibunuh dan harta mereka tidak diambil. Mengapa?", ""),
 (557, 566, S, "", "Kerana mereka telah menyebut dua kalimah syahadah, walaupun dalam hati mereka munafik.", ""),
 (567, 574, S, "", "Mengapa? Kerana kita tidak diperintahkan menyelidik hati manusia.", ""),
 (575, 581, S, "", "Hati mereka terserah kepada Allah, dan Allah memberi amaran dan ancaman kepada mereka lalu berfirman:", ""),
 (582, 588, Q, "إِنَّ ٱلْمُنَـٰفِقِينَ فِى ٱلدَّرْكِ ٱلْأَسْفَلِ مِنَ ٱلنَّارِ",
  "“Sesungguhnya orang-orang munafik itu ditempatkan pada tingkatan yang terkebawah sekali dari neraka…”", "Surah an-Nisa’, 4:145"),
 (589, 600, S, "", "Tetapi kita melayan mereka mengikut apa yang zahir. Oleh itu Nabi ﷺ bersabda:", ""),
 (601, 613, H, "«إِنِّي لَمْ أُومَرْ أَنْ أَشُقَّ عَنْ قُلُوبِ النَّاسِ، إِنَّمَا أُعَامِلُ النَّاسَ بِمَا يُظْهِرُونَ»",
  "“Sesungguhnya aku tidak diperintahkan membelah hati manusia; aku hanya melayan manusia mengikut apa yang mereka zahirkan.”", ""),
 (614, 621, S, "", "Hati mereka tidak dibelah — selawat dan salam Tuhanku ke atasnya.", ""),
 (622, 626, S, "", "Nabi ﷺ bersabda kepada Ali pada hari Khaibar:", ""),
 (627, 654, H, "«قَاتِلْهُمْ عَلَى أَنْ يَشْهَدُوا " + SHAHADAH + "، فَإِنْ فَعَلُوا ذَلِكَ عَصَمُوا مِنْكَ دِمَاءَهُمْ وَأَمْوَالَهُمْ إِلَّا بِحَقِّهَا، وَحِسَابُهُمْ عَلَى اللهِ»",
  "“Perangilah mereka — iaitu Yahudi — sehingga mereka bersaksi bahawa tiada tuhan melainkan Allah dan Muhammad itu utusan Allah. Jika mereka berbuat demikian, terpeliharalah darah dan harta mereka daripadamu kecuali dengan haknya, dan perhitungan mereka atas Allah.”", "Riwayat Muslim"),
 (655, 664, S, "", "Jika sesebuah kumpulan enggan melaksanakan syariat — penduduk sesebuah negeri, contohnya, enggan menunaikan zakat,", ""),
 (665, 676, S, "", "penduduk negeri lain enggan berpuasa, penduduk lain pula enggan, contohnya, solat —", ""),
 (677, 687, S, "", "mereka enggan melaksanakan mana-mana syariat, maka mereka diperangi kerana itu; kumpulan yang enggan itu diperangi.", ""),
 (688, 691, S, "", "Allah Ta‘ala berfirman:", ""),
 (692, 700, Q, "وَقَـٰتِلُوهُمْ حَتَّىٰ لَا تَكُونَ فِتْنَةٌ وَيَكُونَ ٱلدِّينُ كُلُّهُۥ لِلَّهِ",
  "“Dan perangilah mereka sehingga tidak ada lagi fitnah, dan (sehingga) menjadilah ugama itu seluruhnya (bebas) bagi Allah semata-mata…”", "Surah al-Anfal, 8:39"),
 (701, 721, S, "", "Apabila Nabi ﷺ memerangi sesuatu kaum, baginda menunggu: jika mereka mendengar azan, baginda menahan diri daripada mereka; jika tidak, baginda menyerang mereka.", ""),
 (722, 730, S, "", "Ini menunjukkan bahawa menegakkan syiar Islam itulah yang memelihara daripada pembunuhan.", ""),
 (731, 746, S, "", "Sabdanya “kecuali dengan hak Islam” — hak Islam ialah yang datang dalam hadis Ibn Mas‘ud dalam dua kitab Sahih, dan akan datang kepada kita:", ""),
 (747, 762, H, "«لَا يَحِلُّ دَمُ امْرِئٍ مُسْلِمٍ إِلَّا بِإِحْدَى ثَلَاثٍ: الثَّيِّبُ الزَّانِي، وَالنَّفْسُ بِالنَّفْسِ، وَالتَّارِكُ لِدِينِهِ الْمُفَارِقُ لِلْجَمَاعَةِ»",
  "“Tidak halal darah seorang Muslim kecuali dengan salah satu daripada tiga perkara: orang yang pernah berkahwin lalu berzina, nyawa dibalas dengan nyawa, dan orang yang meninggalkan agamanya lagi memisahkan diri daripada jemaah.”", "Riwayat al-Bukhari dan Muslim"),
 (763, 771, S, "", "Inilah makna sabdanya “kecuali dengan hak Islam”, iaitu sesiapa yang", ""),
 (772, 794, S, "", "melakukan sesuatu yang menghalalkan darahnya, seperti pembunuh, pengintip, perosak di muka bumi, penzina muhsan dan perkara lain, sebagaimana akan dijelaskan nanti, insya-Allah Ta‘ala.", ""),
 (795, 798, H, "«وحِسَابُهُم على اللَّه»", "Sabdanya: “dan perhitungan mereka atas Allah”", ""),
 (799, 811, S, "", "Perhitungan batin mereka terserah kepada Allah, kerana hanya Dialah yang mengetahui apa yang ada dalam hati,", ""),
 (812, 825, S, "", "daripada kekufuran, kemunafikan dan lain-lain. Sesiapa yang ikhlas dalam imannya, Allah Tabaraka wa Ta‘ala akan membalasnya dengan balasan orang yang ikhlas.", ""),
 (826, 840, S, "", "Dan sesiapa yang tidak berbuat demikian, dilaksanakan ke atasnya di dunia hukum-hukum kaum Muslimin, kerana kita melayan manusia mengikut apa yang zahir,", ""),
 (841, 848, S, "", "dan di akhirat azab menimpanya daripada ‘Allamul Ghuyub (Maha Mengetahui yang ghaib), Yang —", ""),
 (849, 856, Q, "يَعْلَمُ خَآئِنَةَ ٱلْأَعْيُنِ وَمَا تُخْفِى ٱلصُّدُورُ",
  "“Allah mengetahui pengkhianatan (penyelewengan dan ketiadaan jujur) pandangan mata seseorang, serta mengetahui akan apa yang tersembunyi di dalam hati.”", "Surah Ghafir, 40:19"),
]
